def is_anagram(s, t):
    if len(s) != len(t): return False
    cnt = [0]*26
    for a, b in zip(s, t):
        cnt[ord(a)-97] += 1
        cnt[ord(b)-97] -= 1
    return all(x == 0 for x in cnt)

